package vn.eventplatform.ad.controller;
import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import vn.eventplatform.ad.dto.*; import vn.eventplatform.ad.service.AdService; import vn.eventplatform.common.dto.ApiResponse; import java.math.BigDecimal; import java.util.*;
@RestController @RequiredArgsConstructor public class AdController { private final AdService service; private final vn.eventplatform.ad.service.CloudinaryUploadService cloudinary; private UUID me(Authentication a){return UUID.fromString(a.getPrincipal().toString());}
 @GetMapping("/api/v1/public/banners") public ApiResponse<List<Responses.BannerResponse>> publicBanners(){return ApiResponse.ok(service.publicBanners());}
 @GetMapping("/api/v1/admin/ad-packages") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<List<Responses.PackageResponse>> packages(){return ApiResponse.ok(service.packageAll());}
 @PostMapping("/api/v1/admin/ad-packages") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<Responses.PackageResponse>> createPackage(@Valid @RequestBody Requests.PackageRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok(service.packageCreate(r)));}
 @PutMapping("/api/v1/admin/ad-packages/{id}") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<Responses.PackageResponse> updatePackage(@PathVariable UUID id,@Valid @RequestBody Requests.PackageRequest r){return ApiResponse.ok(service.packageUpdate(id,r));}
 @DeleteMapping("/api/v1/admin/ad-packages/{id}") @PreAuthorize("hasRole('ADMIN')") public void deletePackage(@PathVariable UUID id){service.packageDelete(id);}
 @PostMapping("/api/v1/organizer/ad-campaigns") @PreAuthorize("hasRole('ORGANIZER')") public ResponseEntity<ApiResponse<Responses.CampaignResponse>> register(Authentication a,@Valid @RequestBody Requests.CampaignRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok(service.register(me(a),r)));}
 @GetMapping("/api/v1/organizer/ad-campaigns") @PreAuthorize("hasRole('ORGANIZER')") public ApiResponse<List<Responses.CampaignResponse>> mine(Authentication a){return ApiResponse.ok(service.organizerCampaigns(me(a)));}
 @PostMapping("/api/v1/admin/ad-campaigns/{id}/approve") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<Responses.CampaignResponse> approve(@PathVariable UUID id){return ApiResponse.ok(service.approve(id));}
 @PostMapping("/api/v1/admin/ad-campaigns/{id}/reject") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<Responses.CampaignResponse> reject(@PathVariable UUID id,@RequestBody Requests.DecisionRequest r){return ApiResponse.ok(service.reject(id,r.reason()));}
 @PostMapping("/internal/v1/ad-campaigns/{id}/settlement") public ApiResponse<BigDecimal> settlement(@PathVariable UUID id){service.publishSettlement(id);return ApiResponse.ok(service.postpaidFee(id));}
 @PostMapping("/api/v1/admin/banners") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ApiResponse<Responses.BannerResponse>> banner(@Valid @RequestBody Requests.BannerRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.ok(service.banner(r)));}
 @PostMapping(value="/api/v1/admin/banners/upload",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @PreAuthorize("hasRole('ADMIN')") public ApiResponse<String> upload(@RequestParam("file") org.springframework.web.multipart.MultipartFile file){return ApiResponse.ok(cloudinary.upload(file));}
 @PutMapping("/api/v1/admin/banners/{id}") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<Responses.BannerResponse> bannerUpdate(@PathVariable UUID id,@Valid @RequestBody Requests.BannerRequest r){return ApiResponse.ok(service.bannerUpdate(id,r));}
 @PostMapping("/api/v1/admin/banners/{id}/approve-image") @PreAuthorize("hasRole('ADMIN')") public ApiResponse<Responses.BannerResponse> imageApprove(@PathVariable UUID id){return ApiResponse.ok(service.approveImage(id));}
 @DeleteMapping("/api/v1/admin/banners/{id}") @PreAuthorize("hasRole('ADMIN')") public void bannerDelete(@PathVariable UUID id){service.deleteBanner(id);}}
